// @ts-check
/*
 * settings.js — persisted preferences (chrome.storage.local, isolated world only).
 *
 * The two lines are fixed: English on top, Simplified Chinese below (see
 * content.js). Only presentation and the reading assist are configurable.
 */
var MC_SETTINGS = (() => {
  /**
   * @typedef {{scale: number, bottom: number, slotScale: number[], backdrop: boolean}} Style
   * scale: overall font size multiplier; bottom: distance from the picture's bottom edge in %;
   * slotScale: per-line multipliers (top, bottom); backdrop: translucent box behind each line.
   */
  /** @typedef {'none' | 'above' | 'below'} Pinyin */
  /**
   * @typedef {{pause: 'off' | 'timed' | 'manual', secondsPerChar: number, extend: boolean}} Assist
   * pause: hold the caption before it vanishes and resume after the reading time (timed) or
   * wait for the viewer (manual); extend: let captions linger into silence.
   */
  /** @typedef {{enabled: boolean, pinyin: Pinyin, style: Style, assist: Assist}} Settings */
  const KEY = 'multicap';
  /** @type {Style} */
  const DEFAULT_STYLE = { scale: 1, bottom: 7, slotScale: [1, 1.15], backdrop: false };
  const PINYIN_MODES = ['none', 'above', 'below'];
  /** Allowed ranges for the sliders; anything outside is clamped on load and save. */
  const RANGES = { scale: [0.6, 1.8], bottom: [2, 30], slotScale: [0.6, 1.8] };
  /** @type {Settings} */
  /** @type {Assist} */
  const DEFAULT_ASSIST = { pause: 'off', secondsPerChar: 0.4, extend: true };
  const ASSIST_RANGES = { secondsPerChar: [0.15, 1.0] };
  const PAUSE_MODES = ['off', 'timed', 'manual'];
  const DEFAULTS = { enabled: true, pinyin: 'below', style: DEFAULT_STYLE, assist: DEFAULT_ASSIST };
  /** @type {Settings | null} */
  let cache = null;
  /** @type {Array<(s: Settings) => void>} */
  const listeners = [];

  /** @returns {Promise<Settings>} */
  async function load() {
    try {
      const r = await chrome.storage.local.get(KEY);
      cache = normalize(r && r[KEY]);
    } catch (err) {
      MC_UTIL.warn('settings: chrome.storage.local unavailable, using defaults:', err);
      cache = normalize(null);
    }
    return cache;
  }

  /** @param {any} raw @returns {Settings} */
  function normalize(raw) {
    const s = { ...DEFAULTS, ...(raw && typeof raw === 'object' ? raw : {}) };
    delete s.langs; // language slots existed in earlier builds
    s.enabled = s.enabled !== false;
    const st = { ...DEFAULT_STYLE, ...(s.style && typeof s.style === 'object' ? s.style : {}) };
    // pinyin was a boolean plus style.rubyUnder in earlier builds
    if (typeof s.pinyin === 'boolean') s.pinyin = s.pinyin ? (st.rubyUnder === false ? 'above' : 'below') : 'none';
    if (!PINYIN_MODES.includes(s.pinyin)) s.pinyin = DEFAULTS.pinyin;
    delete st.rubyUnder;
    const clamp = (/** @type {any} */ v, /** @type {number[]} */ r, /** @type {number} */ d) => (typeof v === 'number' && Number.isFinite(v) ? Math.min(r[1], Math.max(r[0], v)) : d);
    st.scale = clamp(st.scale, RANGES.scale, DEFAULT_STYLE.scale);
    st.bottom = clamp(st.bottom, RANGES.bottom, DEFAULT_STYLE.bottom);
    st.slotScale = [0, 1].map((i) => clamp(Array.isArray(st.slotScale) ? st.slotScale[i] : undefined, RANGES.slotScale, DEFAULT_STYLE.slotScale[i]));
    st.backdrop = st.backdrop === true;
    s.style = st;
    const a = { ...DEFAULT_ASSIST, ...(s.assist && typeof s.assist === 'object' ? s.assist : {}) };
    // earlier builds stored mode ('off' | 'pause' | 'slow' | 'slowpause') + autoResume
    if (typeof a.mode === 'string') { a.pause = a.mode === 'off' ? 'off' : a.autoResume === false ? 'manual' : 'timed'; }
    if (!PAUSE_MODES.includes(a.pause)) a.pause = 'off';
    delete a.mode; delete a.autoResume; delete a.minRate; delete a.lastMode;
    a.secondsPerChar = clamp(a.secondsPerChar, ASSIST_RANGES.secondsPerChar, DEFAULT_ASSIST.secondsPerChar);
    a.extend = a.extend !== false;
    s.assist = a;
    return s;
  }

  /** @param {{enabled?: boolean, pinyin?: Pinyin, style?: Partial<Style>, assist?: Partial<Assist>}} patch @returns {Promise<Settings>} */
  async function save(patch) {
    const cur = cache || DEFAULTS;
    cache = normalize({ ...cur, ...patch, style: { ...cur.style, ...(patch.style || {}) }, assist: { ...cur.assist, ...(patch.assist || {}) } });
    try { await chrome.storage.local.set({ [KEY]: cache }); } catch (err) { MC_UTIL.warn('settings: save failed:', err); }
    for (const fn of listeners) { try { fn(cache); } catch (err) { MC_UTIL.warn('settings listener threw:', err); } }
    return cache;
  }

  /** @returns {Settings} */
  function get() { return cache || normalize(null); }

  /** @param {(s: Settings) => void} fn */
  function onChange(fn) { listeners.push(fn); }

  return { DEFAULTS, DEFAULT_STYLE, RANGES, PINYIN_MODES, DEFAULT_ASSIST, ASSIST_RANGES, PAUSE_MODES, load, save, get, onChange, normalize };
})();

// ===== src/pinyin.js =====
// @ts-check
/*
 * pinyin.js — annotate a Simplified Chinese line with per-character pinyin (isolated world).
 *
 * Dictionary: data/pinyin.json, built by tools/build-pinyin.js from the DuiDuiDui corpus
 * (words → one syllable per character; characters → readings in sense order). Loaded once,
 * lazily, through the extension's own URL.
 *
 * Segmentation: Intl.Segmenter word boundaries first (ICU's Chinese dictionary), then the
 * longest dictionary match inside any chunk the dictionary does not know, then single
 * characters with their first reading. Word lookup is what gets heteronyms right
 * (银行 yín háng, 睡着 shuì zháo); the per-character fallback is sense-ordered so 了 → le,
 * 地 → de, 得 → de on their own.
 */
var MC_PINYIN = (() => {
  /** @typedef {{text: string, syl: string[] | null, word: boolean}} Segment  syl null = not annotated */
  const HAN = /\p{Script=Han}/u;
  const MAX_WORD = 6;

  /** @type {{words: Record<string, string>, chars: Record<string, string[]>, meta?: any} | null} */
  let dict = null;
  /** @type {Promise<any> | null} */
  let loading = null;
  /** @type {Intl.Segmenter | null} */
  let segmenter = null;
  /** @type {Map<string, Segment[]>} */
  const cache = new Map();

  /** @param {any} d */
  function use(d) {
    if (!d || typeof d !== 'object' || !d.words || !d.chars) throw new Error('pinyin: not a dictionary');
    dict = d;
    cache.clear();
    try { segmenter = new Intl.Segmenter('zh-Hans', { granularity: 'word' }); } catch { segmenter = null; }
  }

  /** @param {string} url @returns {Promise<void>} */
  function load(url) {
    if (dict) return Promise.resolve();
    if (!loading) {
      loading = fetch(url)
        .then((r) => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
        .then((d) => { use(d); })
        .catch((err) => { loading = null; throw err; });
    }
    return loading;
  }

  function isReady() { return !!dict; }

  /** Split into runs of Han vs non-Han. @param {string} s */
  function runs(s) {
    /** @type {Array<{text: string, han: boolean}>} */
    const out = [];
    for (const ch of s) {
      const han = HAN.test(ch);
      const last = out[out.length - 1];
      if (last && last.han === han) last.text += ch; else out.push({ text: ch, han });
    }
    return out;
  }

  /** Longest dictionary match over a Han run, single characters as the fallback. @param {string} run @param {Segment[]} out */
  function matchRun(run, out) {
    if (!dict) return;
    const cps = [...run];
    let i = 0;
    while (i < cps.length) {
      let hit = null;
      for (let len = Math.min(MAX_WORD, cps.length - i); len >= 2; len--) {
        const w = cps.slice(i, i + len).join('');
        const r = dict.words[w];
        if (r) { hit = { w, syl: r.split(' '), len }; break; }
      }
      if (hit) {
        out.push({ text: hit.w, syl: hit.syl, word: true });
        i += hit.len;
      } else {
        const c = cps[i];
        const rs = dict.chars[c];
        out.push({ text: c, syl: rs && rs.length ? [rs[0]] : null, word: false });
        i++;
      }
    }
  }

  /**
   * @param {string} text
   * @returns {Segment[] | null} null when the dictionary is not loaded
   */
  function annotate(text) {
    if (!dict) return null;
    const hit = cache.get(text);
    if (hit) return hit;
    /** @type {Segment[]} */
    const out = [];
    const chunks = segmenter ? [...segmenter.segment(text)].map((s) => s.segment) : [text];
    for (const chunk of chunks) {
      for (const run of runs(chunk)) {
        if (!run.han) { out.push({ text: run.text, syl: null, word: false }); continue; }
        const r = dict.words[run.text];
        if (r && [...run.text].length >= 2) out.push({ text: run.text, syl: r.split(' '), word: true });
        else matchRun(run.text, out);
      }
    }
    // merge adjacent plain runs so the DOM stays small
    /** @type {Segment[]} */
    const merged = [];
    for (const s of out) {
      const last = merged[merged.length - 1];
      if (last && !last.syl && !s.syl) last.text += s.text; else merged.push(s);
    }
    if (cache.size > 500) cache.clear();
    cache.set(text, merged);
    return merged;
  }

  /** Flat "字(zì) 字(zì)" form for logs and the console helper. @param {string} text */
  function describe(text) {
    const segs = annotate(text);
    if (!segs) return '(dictionary not loaded)';
    return segs.map((s) => (s.syl ? [...s.text].map((c, i) => `${c}(${s.syl ? s.syl[i] ?? '?' : ''})`).join('') : s.text)).join('');
  }

  return { use, load, isReady, annotate, describe, get size() { return dict ? { words: Object.keys(dict.words).length, chars: Object.keys(dict.chars).length } : null; } };
})();

// ===== src/assist.js =====
// @ts-check
/*
 * assist.js — reading assist: give each Chinese caption a minimum on-screen time.
 *
 * Reading time = Han characters in the caption × secondsPerChar, measured in wall time
 * from the caption's first frame. Mode `pause`: stop just before the caption would vanish
 * and resume when the time is met. (A slowed-playback mode existed briefly; Chrome's
 * pitch-preserving resampling sounds bad, so it was removed.)
 * Only pauses we started are resumed. A manual pause, a manual resume, a seek, or an ad
 * cancels the current caption's plan. Driven from the render loop plus a wall-clock timer.
 */
var MC_ASSIST = (() => {
  const HAN_RE = /\p{Script=Han}/gu;
  /** Act this many content seconds before the caption's end (≈ 7 frames). */
  const EPS = 0.12;
  /** Don't bother pausing for less than this. */
  const MIN_PAUSE_S = 0.2;

  /** @typedef {{mode: 'off' | 'pause', secondsPerChar: number, autoResume: boolean}} Config */
  /** @typedef {{key: string, chars: number, required: number, startWall: number, end: number, pausedByUs: boolean, acted: boolean, resumeHandle: number, actHandle: number}} Caption */
  /** @typedef {{t: number, wall: number, paused: boolean, inAd: boolean, zh: string, end: number}} Frame */

  /**
   * @param {{pause: () => void, play: () => void, sample?: () => Frame | null, indicate?: (st: {holding: boolean, ms?: number, autoResume?: boolean}) => void}} actions
   *   `sample` returns a fresh frame on demand; the render loop can run at a few frames per
   *   second (observed ~10 fps), so the moment to act is scheduled with a timer as well.
   * @param {(msg: string) => void} log
   */
  function create(actions, log) {
    /** @type {Config} */
    let cfg = { mode: 'off', secondsPerChar: 0.4, autoResume: true };
    /** @type {Caption | null} */
    let cap = null;
    let expectingPause = false;
    const stats = { captions: 0, paused: 0, resumed: 0, cancelled: 0 };
    /** Last decisions, for diagnosing "it didn't pause" reports. */
    const trace = MC_UTIL.ring(40);
    /** @type {{t: number, paused: boolean} | null} last frame seen for the current caption */
    let lastFrame = null;
    let lastWall = 0;
    let frameGapMs = 0;
    /** @param {string} ev @param {Record<string, any>} [x] */
    const tr = (ev, x = {}) => trace.push({ ev, at: +(performance.now() / 1000).toFixed(1), ...x });
    /** Tell the overlay what we are doing. @param {{holding: boolean, ms?: number, autoResume?: boolean}} st */
    const indicate = (st) => { if (actions.indicate) { try { actions.indicate(st); } catch { /* overlay gone */ } } };

    /** @param {Partial<Config>} c */
    function configure(c) {
      cfg = { ...cfg, ...c };
      if (cfg.mode === 'off') reset();
    }

    /** Drop the current caption's plan: cancel pending timers. Never resumes a pause. */
    function reset() {
      if (!cap) return;
      if (!cap.acted) tr('drop-unacted', { key: cap.key.slice(0, 12), end: cap.end, lastT: lastFrame && lastFrame.t, lastPaused: lastFrame && lastFrame.paused });
      if (cap.resumeHandle) clearTimeout(cap.resumeHandle);
      if (cap.actHandle) clearTimeout(cap.actHandle);
      if (cap.pausedByUs) indicate({ holding: false });
      cap = null;
      lastFrame = null;
    }

    /**
     * Schedule the act moment by wall clock: frames may be sparse, timers are not.
     * @param {Caption} c @param {Frame} f
     */
    function scheduleAct(c, f) {
      if (f.paused) return;
      const ms = Math.max(0, (c.end - EPS - f.t) * 1000) + 5;
      c.actHandle = window.setTimeout(() => {
        if (cap !== c || c.acted || !actions.sample) return;
        const g = actions.sample();
        if (!g || g.zh + '@' + g.end !== c.key || g.paused || g.inAd) { tr('timer-skip', { reason: !g ? 'no sample' : g.paused ? 'paused' : g.inAd ? 'ad' : 'caption changed' }); return; }
        tr('timer', { t: +g.t.toFixed(3), end: c.end });
        act(g);
      }, ms);
    }

    /** The caption is about to vanish: pause if reading time is still owed. @param {Frame} f */
    function act(f) {
      const c = cap;
      if (!c || c.acted) return;
      c.acted = true;
      if (c.actHandle) { clearTimeout(c.actHandle); c.actHandle = 0; }
      tr('act', { t: +f.t.toFixed(3), elapsed: +((f.wall - c.startWall) / 1000).toFixed(2), required: c.required });
      const elapsed = (f.wall - c.startWall) / 1000;
      const needed = c.required - elapsed;
      if (needed < MIN_PAUSE_S) return;
      c.pausedByUs = true;
      expectingPause = true;
      stats.paused++;
      actions.pause();
      indicate({ holding: true, ms: needed * 1000, autoResume: cfg.autoResume });
      log(`assist: paused ${needed.toFixed(1)}s for ${c.chars} chars "${f.zh.slice(0, 24)}"`);
      if (cfg.autoResume) c.resumeHandle = window.setTimeout(() => resume('reading time met'), needed * 1000);
    }

    /**
     * One frame. `zh` is the Chinese caption text ('' when none), `end` its content end time.
     * @param {{t: number, wall: number, paused: boolean, inAd: boolean, zh: string, end: number}} f
     */
    function update(f) {
      if (cfg.mode === 'off') return;
      if (lastWall) frameGapMs = frameGapMs ? frameGapMs * 0.8 + (f.wall - lastWall) * 0.2 : f.wall - lastWall;
      lastWall = f.wall;
      if (f.inAd || !f.zh) {
        if (cap && !cap.pausedByUs) reset();
        return;
      }
      if (cap && cap.pausedByUs) return; // holding for the reader; the clock is frozen anyway
      const key = f.zh + '@' + f.end; // text alone would merge back-to-back identical captions
      if (!cap || cap.key !== key) {
        reset();
        const chars = (f.zh.match(HAN_RE) || []).length;
        cap = { key, chars, required: chars * cfg.secondsPerChar, startWall: f.wall, end: f.end, pausedByUs: false, acted: false, resumeHandle: 0, actHandle: 0 };
        stats.captions++;
        tr('new', { key: key.slice(0, 12), t: +f.t.toFixed(3), end: +f.end.toFixed(3), chars, paused: f.paused });
        scheduleAct(cap, f);
        return;
      }
      lastFrame = { t: +f.t.toFixed(3), paused: f.paused };
      if (cap.acted || f.paused) return;
      if (f.t < cap.end - EPS) return;
      act(f);
    }

    /** @param {string} why */
    function resume(why) {
      if (!cap || !cap.pausedByUs) return;
      cap.pausedByUs = false;
      cap.resumeHandle = 0;
      stats.resumed++;
      indicate({ holding: false });
      tr('resume', { why });
      log(`assist: resumed (${why})`);
      actions.play();
    }

    /** video 'pause' event: ours, or the user's. */
    function onVideoPause() {
      if (expectingPause) { expectingPause = false; tr('pause-ours'); return; }
      tr('pause-manual', { cap: cap ? cap.key.slice(0, 12) : null, pausedByUs: cap ? cap.pausedByUs : null });
      if (cap) { // manual pause: leave it alone, and don't act again on this caption
        if (cap.resumeHandle) clearTimeout(cap.resumeHandle);
        if (cap.actHandle) { clearTimeout(cap.actHandle); cap.actHandle = 0; }
        cap.pausedByUs = false;
        cap.acted = true;
        stats.cancelled++;
        indicate({ holding: false });
      }
    }

    /** video 'play' event: the user (or we) resumed. */
    function onVideoPlay() {
      tr('play', { cap: cap ? cap.key.slice(0, 12) : null, pausedByUs: cap ? cap.pausedByUs : null });
      if (cap && cap.pausedByUs) {
        if (cap.resumeHandle) clearTimeout(cap.resumeHandle);
        cap.pausedByUs = false;
        cap.resumeHandle = 0;
        stats.cancelled++;
        indicate({ holding: false });
      }
    }

    function status() {
      return { mode: cfg.mode, secondsPerChar: cfg.secondsPerChar, autoResume: cfg.autoResume, frameGapMs: Math.round(frameGapMs), stats, current: cap ? { chars: cap.chars, required: +cap.required.toFixed(2), pausedByUs: cap.pausedByUs, acted: cap.acted } : null, trace: trace.items() };
    }

    return { configure, update, reset, resume, onVideoPause, onVideoPlay, status, get holding() { return !!(cap && cap.pausedByUs); } };
  }

  return { create };
})();

// ===== src/picker.js =====
// @ts-check
/*
 * picker.js — the in-player track picker (isolated world, DOM only).
 *
 * A small pill in the top-right corner ("EN + 简") shows while Netflix's controls
 * are visible; clicking it (or Ctrl+Shift+M) opens the settings panel. The two
 * lines are fixed (English over Simplified Chinese); the pill reflects what the
 * current title actually has. Mounted inside the player view so it survives
 * fullscreen. Styles go through CSSOM.
 */
var MC_PICKER = (() => {
  const FONT = '"Netflix Sans", "Helvetica Neue", Helvetica, Arial, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif';
  const PILL_CSS = 'position:absolute;top:11%;right:2.5%;z-index:20;pointer-events:auto;cursor:pointer;font-family:' + FONT + ';font-size:14px;font-weight:600;letter-spacing:.02em;color:#fff;background:rgba(20,20,20,.72);border:1px solid rgba(255,255,255,.28);border-radius:999px;padding:6px 12px;line-height:1;backdrop-filter:blur(6px);transition:opacity .2s;';
  const PANEL_CSS = 'position:absolute;top:calc(11% + 40px);right:2.5%;z-index:21;pointer-events:auto;font-family:' + FONT + ';font-size:14px;color:#fff;background:rgba(18,18,18,.94);border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:14px 16px 12px;min-width:340px;max-height:70%;overflow:auto;box-shadow:0 12px 40px rgba(0,0,0,.6);backdrop-filter:blur(10px);';
  const HEAD_CSS = 'display:block;padding:5px 0;color:rgba(255,255,255,.55);font-size:12px;text-transform:uppercase;letter-spacing:.08em;';
  const RADIO_CSS = 'justify-self:center;width:16px;height:16px;margin:0;accent-color:#e50914;cursor:pointer;';

  /** @type {Record<string, string>} */
  const SHORT = { en: 'EN', 'zh-hans': '简', 'zh-hant': '繁' };
  /** @param {string | null | undefined} lang */
  function short(lang) {
    if (!lang) return '–';
    const k = lang.toLowerCase();
    return SHORT[k] || k.split('-')[0].toUpperCase();
  }

  const SLIDER_CSS = 'width:100%;margin:0;accent-color:#e50914;cursor:pointer;';
  const SLIDER_ROW_CSS = 'display:grid;grid-template-columns:110px 1fr 76px;align-items:center;gap:10px;padding:4px 0;';

  /**
   * @param {{onEnabled: (enabled: boolean) => void, onPinyin: (mode: string) => void, onStyle: (patch: {scale?: number, bottom?: number, slotScale?: number[], backdrop?: boolean}) => void, onAssist: (patch: {pause?: string, secondsPerChar?: number, extend?: boolean}) => void}} handlers
   */
  function create(handlers) {
    /** @type {HTMLElement | null} */
    let host = null;
    /** @type {HTMLButtonElement | null} */
    let pill = null;
    /** @type {HTMLDivElement | null} */
    let panelEl = null;
    let open = false;
    let controlsVisible = false;
    /**
     * `resolved`: the language actually used for each line on the current title
     * (null = no usable track), e.g. ['en', 'zh-Hant'] when Simplified is missing;
     * it only feeds the pill.
     * @type {{enabled: boolean, pinyin: string, resolved: Array<string | null>, style: {scale: number, bottom: number, slotScale: number[], backdrop: boolean}, assist: {pause: string, secondsPerChar: number, extend: boolean}}}
     */
    let state = { enabled: true, pinyin: 'below', resolved: ['en', 'zh-Hans'], style: { scale: 1, bottom: 7, slotScale: [1, 1.15], backdrop: false }, assist: { pause: 'off', secondsPerChar: 0.4, extend: true } };

    /** @param {HTMLElement} container */
    function mount(container) {
      if (host === container && pill && pill.isConnected) return;
      unmount();
      host = container;
      pill = document.createElement('button');
      pill.className = 'multicap-pill';
      pill.type = 'button';
      pill.style.cssText = PILL_CSS;
      pill.title = 'multicap: choose subtitle tracks (Ctrl+Shift+M)';
      pill.addEventListener('click', (e) => { e.stopPropagation(); toggle(); });
      panelEl = document.createElement('div');
      panelEl.className = 'multicap-panel';
      panelEl.style.cssText = PANEL_CSS + 'display:none;';
      for (const ev of ['click', 'mousedown', 'mouseup', 'keydown', 'keyup', 'pointerdown', 'pointerup']) panelEl.addEventListener(ev, (e) => e.stopPropagation());
      host.appendChild(pill);
      host.appendChild(panelEl);
      renderPill();
      renderPanel();
      updatePillVisibility();
    }

    function unmount() {
      if (pill) pill.remove();
      if (panelEl) panelEl.remove();
      pill = null; panelEl = null; host = null; open = false;
    }

    /** @param {{enabled?: boolean, pinyin?: string, resolved?: Array<string | null>, style?: any, assist?: any}} st */
    function setState(st) {
      state = { ...state, ...st };
      renderPill();
      if (!sliding) renderPanel();
    }
    /** True while a slider is being dragged, so live style updates don't rebuild the panel under the pointer. */
    let sliding = false;

    /** @param {boolean} v */
    function setControlsVisible(v) {
      if (v === controlsVisible) return;
      controlsVisible = v;
      updatePillVisibility();
    }

    /** @param {boolean} [force] */
    function toggle(force) {
      open = force ?? !open;
      if (panelEl) panelEl.style.display = open ? '' : 'none';
      updatePillVisibility();
    }

    function updatePillVisibility() {
      if (!pill) return;
      const show = open || controlsVisible;
      pill.style.opacity = show ? '1' : '0';
      pill.style.pointerEvents = show ? 'auto' : 'none';
    }

    function renderPill() {
      if (!pill) return;
      const a = short(state.resolved[0]);
      const b = short(state.resolved[1]);
      pill.textContent = state.enabled ? `${a} + ${b}` : `${a} + ${b}  (off)`;
      pill.style.opacity = '';
      pill.style.textDecoration = state.enabled ? '' : 'line-through';
      updatePillVisibility();
    }

    /**
     * A two-or-more-state segmented control.
     * @param {Array<[string, string]>} options [value, label]
     * @param {string} value the selected value
     * @param {(value: string) => void} onChange
     */
    function segmented(options, value, onChange) {
      const box = document.createElement('div');
      box.style.cssText = 'display:inline-flex;border:1px solid rgba(255,255,255,.28);border-radius:999px;overflow:hidden;';
      for (const [v, label] of options) {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = label;
        const on = v === value;
        b.style.cssText = 'border:none;padding:4px 12px;font:inherit;font-size:13px;cursor:pointer;line-height:1.2;' + (on ? 'background:#e50914;color:#fff;' : 'background:transparent;color:rgba(255,255,255,.75);');
        b.addEventListener('click', () => { if (v !== value) onChange(v); });
        box.appendChild(b);
      }
      return box;
    }

    /** @param {string} text @param {string} css */
    function el(text, css) {
      const d = document.createElement('div');
      d.textContent = text;
      d.style.cssText = css;
      return d;
    }

    function renderPanel() {
      const panel = panelEl;
      if (!panel) return;
      panel.textContent = '';
      const title = document.createElement('div');
      title.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;';
      title.appendChild(el('multicap', 'font-weight:700;font-size:15px;letter-spacing:.04em;'));
      const close = document.createElement('button');
      close.type = 'button';
      close.textContent = '✕';
      close.style.cssText = 'background:none;border:none;color:rgba(255,255,255,.6);font-size:16px;cursor:pointer;padding:2px 6px;';
      close.addEventListener('click', () => toggle(false));
      title.appendChild(close);
      panel.appendChild(title);

      const styleHead = el('Style', HEAD_CSS);
      panel.appendChild(styleHead);
      /**
       * @param {string} label @param {number} value @param {number[]} range @param {number} step
       * @param {(v: number) => string} fmt @param {(v: number) => void} onInput
       */
      const slider = (label, value, range, step, fmt, onInput) => {
        const row = document.createElement('div');
        row.style.cssText = SLIDER_ROW_CSS;
        row.appendChild(el(label, 'color:rgba(255,255,255,.85);'));
        const input = document.createElement('input');
        input.type = 'range';
        input.min = String(range[0]); input.max = String(range[1]); input.step = String(step); input.value = String(value);
        input.style.cssText = SLIDER_CSS;
        const out = el(fmt(value), 'text-align:right;color:rgba(255,255,255,.6);font-variant-numeric:tabular-nums;');
        input.addEventListener('pointerdown', () => { sliding = true; });
        input.addEventListener('pointerup', () => { sliding = false; });
        input.addEventListener('input', () => { const v = parseFloat(input.value); out.textContent = fmt(v); onInput(v); });
        input.addEventListener('change', () => { sliding = false; });
        row.appendChild(input);
        row.appendChild(out);
        panel.appendChild(row);
      };
      const pct = (/** @type {number} */ v) => Math.round(v * 100) + '%';
      const st = state.style;
      slider('Size', st.scale, MC_SETTINGS.RANGES.scale, 0.05, pct, (v) => handlers.onStyle({ scale: v }));
      slider('Height', st.bottom, MC_SETTINGS.RANGES.bottom, 1, (v) => v + '%', (v) => handlers.onStyle({ bottom: v }));
      slider('Top line', st.slotScale[0], MC_SETTINGS.RANGES.slotScale, 0.05, pct, (v) => handlers.onStyle({ slotScale: [v, state.style.slotScale[1]] }));
      slider('Bottom line', st.slotScale[1], MC_SETTINGS.RANGES.slotScale, 0.05, pct, (v) => handlers.onStyle({ slotScale: [state.style.slotScale[0], v] }));
      const py = document.createElement('div');
      py.style.cssText = 'display:flex;align-items:center;gap:8px;padding:6px 0 2px;';
      py.appendChild(el('Pinyin', 'flex:1;'));
      py.appendChild(segmented([['none', 'None'], ['above', 'Above'], ['below', 'Below']], state.pinyin, (v) => handlers.onPinyin(v)));
      panel.appendChild(py);

      const bd = document.createElement('label');
      bd.style.cssText = 'display:flex;align-items:center;gap:8px;padding:6px 0 2px;cursor:pointer;';
      const bdc = document.createElement('input');
      bdc.type = 'checkbox'; bdc.checked = st.backdrop; bdc.style.cssText = 'accent-color:#e50914;width:16px;height:16px;margin:0;';
      bdc.addEventListener('change', () => handlers.onStyle({ backdrop: bdc.checked }));
      bd.appendChild(bdc);
      bd.appendChild(el('Backdrop behind lines', 'flex:1;'));
      panel.appendChild(bd);

      // ---- reading assist ----
      panel.appendChild(el('Reading assist', HEAD_CSS + 'margin-top:10px;'));
      const as = state.assist;
      const row = (/** @type {string} */ label, /** @type {HTMLElement} */ control) => {
        const r = document.createElement('div');
        r.style.cssText = 'display:flex;align-items:center;gap:8px;padding:4px 0;';
        r.appendChild(el(label, 'flex:1;'));
        r.appendChild(control);
        panel.appendChild(r);
      };
      row('Extend into silence', segmented([['off', 'Off'], ['on', 'On']], as.extend ? 'on' : 'off', (v) => handlers.onAssist({ extend: v === 'on' })));
      row('Pause to read', segmented([['off', 'Off'], ['timed', 'Timed'], ['manual', 'Manual']], as.pause, (v) => handlers.onAssist({ pause: v })));
      slider('Reading time', as.secondsPerChar, MC_SETTINGS.ASSIST_RANGES.secondsPerChar, 0.05, (v) => v.toFixed(2) + ' s/char', (v) => handlers.onAssist({ secondsPerChar: v }));

      const foot = document.createElement('label');
      foot.style.cssText = 'display:flex;align-items:center;gap:8px;margin-top:12px;padding-top:10px;border-top:1px solid rgba(255,255,255,.12);cursor:pointer;';
      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.checked = state.enabled;
      cb.style.cssText = 'accent-color:#e50914;width:16px;height:16px;margin:0;';
      cb.addEventListener('change', () => handlers.onEnabled(cb.checked));
      foot.appendChild(cb);
      foot.appendChild(el('Show subtitles', 'flex:1;'));
      foot.appendChild(el('Ctrl+Shift+H', 'color:rgba(255,255,255,.45);font-size:12px;'));
      panel.appendChild(foot);
    }

    return { mount, unmount, setState, setControlsVisible, toggle, get open() { return open; }, get mounted() { return !!(pill && pill.isConnected); } };
  }

  return { create, short };
})();

// ===== src/content.js =====
// @ts-check
/*
 * content.js — extension side (isolated world), document_start.
 *
 * Owns the playback session: when the page hook reports a manifest, pick the
 * configured track, fetch and parse its WebVTT, mount the overlay next to the
 * <video>, and drive it from the content clock on requestAnimationFrame.
 *
 * Keeps the Phase 0 instrumentation (video events, data-uia diffs, ad text,
 * native subtitle cues, URL changes), stamped with media time, because it is
 * how breakage gets diagnosed.
 */
(() => {
  if (typeof MC_UTIL === 'undefined' || typeof MC_NFLX === 'undefined' || typeof MC_BRIDGE === 'undefined') {
    console.error('[multicap] shared modules missing in content.js — dist/ is stale or mis-built; run: npm run build');
    return;
  }
  const U = MC_UTIL;
  const N = MC_NFLX;
  const bridge = MC_BRIDGE.create('ext');
  const startedAt = Date.now();

  /** @type {ReturnType<typeof U.ring<{t: number, media: number | null, kind: string, detail: string}>>} */
  const timeline = U.ring(3000);
  /** @type {ReturnType<typeof U.ring<{media: number | null, content: number, text: string}>>} */
  const nativeCues = U.ring(300);
  /** @type {Map<string, {first: number | null, adds: number, removes: number, muted: boolean}>} */
  const uiaStats = new Map();

  /** @type {HTMLVideoElement | null} */
  let video = null;
  let videoGen = 0;
  let lastSeenTime = 0;

  const mt = () => (video && Number.isFinite(video.currentTime) ? +video.currentTime.toFixed(3) : null);

  /**
   * Record one observation, stamped with media time.
   * @param {string} kind @param {string} [detail] @param {{quiet?: boolean}} [opts]
   */
  function mark(kind, detail = '', opts = {}) {
    const e = { t: Date.now(), media: mt(), kind, detail };
    timeline.push(e);
    if (!opts.quiet) U.log(`@${e.media == null ? '--' : e.media.toFixed(3)}s  ${kind}`, detail);
    return e;
  }

  // ---- video element --------------------------------------------------------------

  const VIDEO_EVENTS = ['loadstart', 'loadedmetadata', 'durationchange', 'play', 'playing', 'pause', 'seeking', 'seeked', 'waiting', 'stalled', 'emptied', 'abort', 'error', 'ended', 'ratechange'];

  /** @param {HTMLVideoElement} v */
  function videoDesc(v) {
    const src = v.currentSrc || v.src || '';
    return `dur=${U.fmtSec(v.duration)} paused=${v.paused} rate=${v.playbackRate} ready=${v.readyState} src=${src ? src.slice(0, 50) : '(none)'}`;
  }

  /** Compare the element's duration (media time) with the manifest's (assumed content time). @param {HTMLVideoElement} v */
  function durationVsManifest(v) {
    const ms = /** @type {any[]} */ (U.safe(() => bridge.call('manifests'), []) ?? []);
    const m = ms[ms.length - 1];
    if (!m || typeof m.durationMs !== 'number' || !Number.isFinite(v.duration)) return 'manifest duration: n/a';
    const videoMs = Math.round(v.duration * 1000);
    return `manifest.duration=${m.durationMs}ms video.duration=${videoMs}ms diff=${videoMs - m.durationMs >= 0 ? '+' : ''}${videoMs - m.durationMs}ms (stitched-ad total?)`;
  }

  function clockLine() {
    const c = U.safe(() => bridge.call('clock'), null);
    if (!c) return 'api clock: bridge unavailable';
    if (c.api) return `api clock: ${c.api}`;
    return `api.currentTime=${c.apiCurrentTime} content=${c.contentTimeMs}ms ad=${c.adPresenting}${c.adBreakIndex != null ? '#' + c.adBreakIndex : ''} api−video=${c.apiMinusVideoMs}ms`;
  }

  /** @param {HTMLVideoElement} v */
  function attachVideo(v) {
    video = v;
    const gen = ++videoGen;
    const all = document.querySelectorAll(N.SEL.video).length;
    mark('video:attach', `#${gen} (${all} video element(s) on page) ${videoDesc(v)}`);
    clock.onSeek();
    assist.reset();
    if (session) overlay.attach(v, SLOTS, overlayHost());
    for (const ev of VIDEO_EVENTS) {
      v.addEventListener(ev, () => {
        if (video !== v) return;
        let extra = '';
        if (ev === 'durationchange' || ev === 'loadedmetadata') extra = '  ' + durationVsManifest(v);
        else if (ev === 'seeking') { extra = `  from=${U.fmtSec(lastSeenTime)} to=${U.fmtSec(v.currentTime)}`; clock.onSeek(); if (session) session.lastShown = null; assist.reset(); }
        else if (ev === 'pause') { assist.onVideoPause(); if (!assist.holding) endResumeGrace(); }
        else if (ev === 'play') { assist.onVideoPlay(); }
        else if (ev === 'seeked') extra = '  ' + clockLine();
        mark('video:' + ev, videoDesc(v) + extra);
      });
    }
  }

  function videoTick() {
    const v = /** @type {HTMLVideoElement | null} */ (document.querySelector(N.SEL.video));
    if (v !== video) {
      if (video && !video.isConnected) mark('video:detached', `#${videoGen}`);
      if (v) attachVideo(v);
      else if (video) { mark('video:gone'); video = null; overlay.detach(); }
    }
    if (video) lastSeenTime = video.currentTime;
  }

  function clockTick() {
    if (!video || video.paused || !video.isConnected) return;
    U.muted(`@${U.fmtSec(mt())} clock  ${videoDesc(video)}  ${clockLine()}`);
    mark('clock', `${videoDesc(video)}  ${clockLine()}`, { quiet: true });
  }

  // ---- DOM discovery: data-uia diffs + ad-word text ---------------------------------

  let uiaPrev = new Set();
  let uiaScheduled = false;
  let warnedNoRoot = false;
  let watchSince = Date.now();

  /** Scope for data-uia diffs: the player shell. Falls back to <body> only after the player has had time to mount. */
  function discoveryRoot() {
    const root = document.querySelector(N.SEL.playerRoot);
    if (root) return root;
    if (!N.watchIdFromUrl(location.href) || Date.now() - watchSince < 10000) return null;
    if (!warnedNoRoot) {
      warnedNoRoot = true;
      U.warn(`on /watch for 10s but no '${N.SEL.playerRoot}' element found; scanning document.body instead (fix SEL.playerRoot in netflix.js)`);
    }
    return document.body;
  }

  function sampleUia() {
    uiaScheduled = false;
    const root = discoveryRoot();
    if (!root) { uiaPrev = new Set(); return; }
    const now = new Set();
    for (const el of root.querySelectorAll('[data-uia]')) now.add(el.getAttribute('data-uia') ?? '');
    if (!uiaPrev.size && now.size) {
      mark('uia:baseline', `${now.size} values: ${[...now].join('  ')}`, { quiet: true });
      for (const v of now) uiaStats.set(v, { first: mt(), adds: 1, removes: 0, muted: false });
      uiaPrev = now;
      return;
    }
    for (const v of now) if (!uiaPrev.has(v)) noteUia(v, '+');
    for (const v of uiaPrev) if (!now.has(v)) noteUia(v, '-');
    uiaPrev = now;
  }

  /** @param {string} v @param {'+' | '-'} sign */
  function noteUia(v, sign) {
    let s = uiaStats.get(v);
    if (!s) uiaStats.set(v, (s = { first: mt(), adds: 0, removes: 0, muted: false }));
    if (sign === '+') s.adds++; else s.removes++;
    if (s.muted) return;
    const adLike = N.AD_TOKEN_RE.test(v);
    const flips = s.adds + s.removes;
    if (flips > 16 && !adLike) {
      s.muted = true;
      mark('uia:mute', `${v} flips too often; muting`, { quiet: true });
      return;
    }
    mark(`uia${sign}`, v + (adLike ? '   <== AD-LIKE' : ''), { quiet: !adLike });
  }

  /** @type {Map<string, number>} */
  const recentAdText = new Map();

  /** @param {Element | null} el @param {string} how */
  function reportAdText(el, how) {
    if (!el) return;
    const text = (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 100);
    if (!text || !N.AD_TEXT_RE.test(text)) return;
    const last = recentAdText.get(text);
    if (last && Date.now() - last < 3000) return;
    recentAdText.set(text, Date.now());
    mark('ad-text:' + how, `"${text}"  <${el.tagName.toLowerCase()} data-uia=${el.getAttribute('data-uia') ?? '-'} class=${(el.getAttribute('class') || '-').slice(0, 60)}>`);
  }

  /** Smallest elements in an added subtree whose text mentions ads. @param {Element} el */
  function scanAdTextTree(el) {
    const whole = el.textContent || '';
    if (!whole || whole.length > 2000 || !N.AD_TEXT_RE.test(whole)) return;
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let n;
    while ((n = walker.nextNode())) if (N.AD_TEXT_RE.test(n.nodeValue || '')) reportAdText(n.parentElement, 'added');
  }

  const observer = new MutationObserver((muts) => {
    if (!uiaScheduled) { uiaScheduled = true; setTimeout(sampleUia, 150); }
    for (const m of muts) {
      if (m.type === 'characterData') reportAdText(m.target.parentElement, 'changed');
      else for (const n of m.addedNodes) {
        if (n.nodeType === Node.ELEMENT_NODE) scanAdTextTree(/** @type {Element} */ (n));
        else if (n.nodeType === Node.TEXT_NODE) reportAdText(n.parentElement, 'added');
      }
    }
  });

  // ---- native subtitle layer (does Netflix keep updating it? what does it show during ads?) ----

  /** @type {Element | null} */
  let ttEl = null;
  let ttLast = '';
  let ttCount = 0;

  function timedTextTick() {
    const el = document.querySelector(N.SEL.timedtext);
    if (el === ttEl) { applyNativeVisibility(); return; }
    ttEl = el;
    ttLast = '';
    if (!el) { mark('native:gone', `${N.SEL.timedtext} left the DOM`); return; }
    const cs = getComputedStyle(el);
    mark('native:attach', `${N.SEL.timedtext} found (opacity=${cs.opacity} display=${cs.display} visibility=${cs.visibility})`);
    applyNativeVisibility();
    const obs = new MutationObserver(() => {
      if (ttEl !== el) { obs.disconnect(); return; }
      const t = (el.textContent || '').trim().replace(/\s+/g, ' ');
      if (t === ttLast) return;
      ttLast = t;
      ttCount++;
      const media = video ? video.currentTime : 0;
      if (t) clock.observeNative(t, media);
      const c = clock.now();
      nativeCues.push({ media: mt(), content: c.t, text: t });
      if (ttCount <= 8) mark('native:cue', t ? `content=${c.t.toFixed(3)} "${t.slice(0, 80)}"` : '(cleared)');
      else if (ttCount === 9) mark('native:cue', '… further native cue changes recorded silently (see summary / __multicap.sync())');
    });
    obs.observe(el, { subtree: true, childList: true, characterData: true });
  }

  // ---- URL + manifest watchdog -------------------------------------------------------

  let lastHref = '';
  let watchdog = 0;
  const WATCHDOG_MS = 25000;

  function urlTick() {
    if (location.href === lastHref) return;
    lastHref = location.href;
    mark('url', lastHref);
    clearTimeout(watchdog);
    const id = N.watchIdFromUrl(lastHref);
    if (!id) { stopSession('left /watch'); return; }
    watchSince = Date.now();
    watchdog = setTimeout(() => {
      const ms = /** @type {any[]} */ (U.safe(() => bridge.call('manifests'), []) ?? []);
      if (ms.some((m) => String(m.movieId) === id)) U.log(`watchdog ok: manifest for /watch/${id} was captured`);
      else U.warn(`on /watch/${id} for ${WATCHDOG_MS / 1000}s but no manifest with movieId=${id} captured (captured: ${ms.map((m) => m.movieId).join(', ') || 'none'}). Neither the player graph (MANIFEST_PATH / findManifest) nor the JSON.parse hook produced it — see src/netflix.js.`);
    }, WATCHDOG_MS);
  }

  // ---- session: tracks → cues → overlay, driven by the content clock ------------------

  /** The two lines, fixed: English on top, Simplified Chinese below. pickTrack() falls back to a base-language match (zh-Hant) when a title lacks zh-Hans. */
  const LANGS = ['en', 'zh-Hans'];
  const SLOTS = LANGS.length;
  const clock = MC_CLOCK.create(bridge, () => video, () => domAd);
  const overlay = MC_OVERLAY.create();

  /**
   * Resume playback through Netflix's own controls when they are on screen (resuming through
   * the player API while the pause card is up leaves the UI stuck on the card), else the API.
   */
  function resumePlayback() {
    const card = document.querySelector(N.SEL.pauseAd);
    const cardBtn = card ? card.closest('[data-uia="pause-ad"]')?.querySelector('button, [role="button"]') : null;
    if (cardBtn instanceof HTMLElement) { cardBtn.click(); mark('assist:resume', 'via pause card button', { quiet: true }); return; }
    const btn = document.querySelector(N.SEL.playButton);
    if (btn instanceof HTMLElement) { btn.click(); mark('assist:resume', 'via control bar', { quiet: true }); return; }
    U.safe(() => bridge.call('play'));
    mark('assist:resume', 'via player API', { quiet: true });
  }
  const assist = MC_ASSIST.create({
    pause: () => { U.safe(() => bridge.call('pause')); },
    play: resumePlayback,
    sample: () => assistFrame(),
    indicate: (st) => { overlay.setIndicator(st); if (st.holding) setHoldingUi(true); else if (holdingUi) startResumeGrace(); },
  }, (msg) => mark('assist', msg));

  /** Netflix also flashes its control bar on resume; keep it hidden that long after our own resumes. */
  const RESUME_GRACE_MS = 3500;
  let graceHandle = 0;
  function startResumeGrace() {
    clearTimeout(graceHandle);
    graceHandle = window.setTimeout(() => { graceHandle = 0; setHoldingUi(false); }, RESUME_GRACE_MS);
  }
  function endResumeGrace() {
    if (!graceHandle) return;
    clearTimeout(graceHandle);
    graceHandle = 0;
    if (!assist.holding) setHoldingUi(false);
  }
  document.addEventListener('pointermove', endResumeGrace, { capture: true, passive: true });

  /**
   * While the assist holds a caption, Netflix's control bar (which it shows on every pause)
   * is hidden and the captions are not raised, so nothing on screen moves. Manual pauses keep
   * Netflix's normal behaviour.
   */
  /** @type {CSSStyleSheet | null} */
  let controlsSheet = null;
  let holdingUi = false;
  /** @param {boolean} on */
  function setHoldingUi(on) {
    if (on === holdingUi) return;
    holdingUi = on;
    try {
      if (!controlsSheet) {
        controlsSheet = new CSSStyleSheet();
        controlsSheet.replaceSync(`${N.SEL.controls} { visibility: hidden !important; }`);
        document.adoptedStyleSheets = [...document.adoptedStyleSheets, controlsSheet];
      }
      controlsSheet.disabled = !on;
    } catch { /* no constructed stylesheets: the bar shows, captions still stay put */ }
    pickerTick();
  }

  /**
   * A fresh frame for the reading assist: content time, the Chinese caption on screen and
   * its end. Used by the render loop and, on demand, by the assist's timers.
   * @returns {{t: number, wall: number, paused: boolean, inAd: boolean, zh: string, end: number} | null}
   */
  function assistFrame() {
    const s = session;
    if (!s || !video) return null;
    const c = clock.now();
    const hidden = (c.movieId != null && String(c.movieId) !== String(s.movieId)) || c.inAd || !MC_SETTINGS.get().enabled;
    let zh = '';
    let end = -Infinity;
    if (!hidden) {
      for (const l of s.lines) {
        if (!l || !l.hans) continue;
        const active = MC_SUBS.activeCues(l.cues, c.t, { i: l.cursor.i });
        zh = active.map((x) => x.text).join('\n');
        for (const x of active) end = Math.max(end, x.end);
      }
    }
    return { t: c.t, wall: performance.now(), paused: video.paused, inAd: c.inAd || hidden, zh, end };
  }
  const picker = MC_PICKER.create({
    onEnabled(enabled) { MC_SETTINGS.save({ enabled }); },
    onPinyin(pinyin) { MC_SETTINGS.save({ pinyin: /** @type {any} */ (pinyin) }); },
    onStyle(patch) { MC_SETTINGS.save({ style: patch }); },
    onAssist(patch) { MC_SETTINGS.save({ assist: /** @type {any} */ (patch) }); },
  });
  /** The overlay's style, with the pinyin position folded in. @param {ReturnType<typeof MC_SETTINGS.get>} st */
  const overlayStyle = (st) => ({ ...st.style, rubyUnder: st.pinyin === 'below' });
  /** The assist's config from the setting: pause off / timed (auto-resume) / manual. @param {ReturnType<typeof MC_SETTINGS.get>} st */
  const assistConfig = (st) => ({ mode: /** @type {'off' | 'pause'} */ (st.assist.pause === 'off' ? 'off' : 'pause'), secondsPerChar: st.assist.secondsPerChar, autoResume: st.assist.pause === 'timed' });
  /** What Ctrl+Shift+P switches back to. */
  let lastPauseMode = 'timed';
  const settingsReady = MC_SETTINGS.load().then((st) => { picker.setState({ enabled: st.enabled, pinyin: st.pinyin, style: st.style, assist: st.assist }); overlay.setStyle(overlayStyle(st)); assist.configure(assistConfig(st)); if (st.assist.pause !== 'off') lastPauseMode = st.assist.pause; return st; });
  MC_SETTINGS.onChange((st) => {
    picker.setState({ enabled: st.enabled, pinyin: st.pinyin, style: st.style, assist: st.assist });
    overlay.setStyle(overlayStyle(st));
    assist.configure(assistConfig(st));
    if (st.assist.pause !== 'off') lastPauseMode = st.assist.pause;
    if (session) applyExtension(session);
    if (session) { session.lastKey = ''; ensurePinyin(session); }
    mark('settings', `enabled=${st.enabled} pinyin=${st.pinyin} style=${JSON.stringify(st.style)} assist=${JSON.stringify(st.assist)}`, { quiet: true });
  });
  let pauseAdPresent = false;
  let controlsVisible = false;
  /** Parsed cue lists by `${movieId}|${trackId}`, so switching a slot back and forth is instant. */
  const cueCache = new Map();

  /** @typedef {{begin: number, end: number, text: string, settings: string, norm?: string}} Cue */
  /** @typedef {{pick: any, cues: Cue[], raw: Cue[], cursor: {i: number}, hans: boolean}} Line */
  const HAN_COUNT_RE = /\p{Script=Han}/gu;

  /**
   * Reading-time extension over the whole transcript: the Chinese line's cues linger into
   * silence up to chars × secondsPerChar; the other line follows so the pair vanishes together.
   * @param {Session} s
   */
  function applyExtension(s) {
    const a = MC_SETTINGS.get().assist;
    const driver = s.lines.find((l) => l && l.hans);
    for (const l of s.lines) if (l) { l.cues = l.raw; l.cursor = { i: 0 }; }
    if (!a.extend || !driver) return;
    driver.cues = MC_SUBS.extendCues(driver.raw, (c) => (c.text.match(HAN_COUNT_RE) || []).length * a.secondsPerChar);
    for (const l of s.lines) if (l && l !== driver) l.cues = MC_SUBS.alignEnds(l.raw, driver.cues);
    s.lastKey = '';
  }
  /** @typedef {{movieId: any, lines: Array<Line | null>, raf: number, lastKey: string, stopped: boolean, startedAt: number, cueChanges: number, lastShown: {texts: string[], end: number} | null}} Session */
  /** While paused, keep the last caption up if it ended no more than this many seconds before the pause point. */
  const STICKY_S = 4;
  /** @type {Session | null} */
  let session = null;

  /** @param {any} movieId */
  function tracksFor(movieId) {
    return /** @type {any[]} */ (U.safe(() => bridge.call('tracks', movieId), []) ?? []);
  }

  /**
   * @param {any} movieId @param {string} why @param {boolean} [force] restart even for the same title
   */
  async function startSession(movieId, why, force) {
    if (!force && session && String(session.movieId) === String(movieId)) return;
    stopSession(why);
    await settingsReady;
    const rows = tracksFor(movieId);
    /** @type {Session} */
    const s = { movieId, lines: [], raf: 0, lastKey: '', stopped: false, startedAt: Date.now(), cueChanges: 0, lastShown: null };
    session = s;
    mark('session:start', `movieId=${movieId} lines=${LANGS.join(' / ')} (${why})`);
    const lines = await Promise.all(LANGS.map((lang, i) => loadLine(movieId, rows, lang, i)));
    if (session !== s) return; // superseded while fetching
    s.lines = lines;
    applyExtension(s);
    picker.setState({ resolved: lines.map((l) => (l ? l.pick.lang : null)) });
    if (!lines.some(Boolean)) {
      mark('session:empty', 'neither an English nor a Chinese text track; overlay stays down');
      session = null;
      applyNativeVisibility();
      return;
    }
    mark('session:ready', lines.map((l, i) => (l ? `${LANGS[i]}→${l.pick.lang} "${l.pick.name}" ${l.cues.length} cues` : `${LANGS[i]}: no track`)).join('; '));
    if (lines[1] && !lines[1].hans) U.warn(`no Simplified Chinese track on movieId=${movieId}; showing ${lines[1].pick.lang} "${lines[1].pick.name}" instead (no pinyin)`);
    ensurePinyin(s);
    if (video) overlay.attach(video, SLOTS, overlayHost());
    applyNativeVisibility();
    s.raf = requestAnimationFrame(frame);
  }

  /**
   * Resolve one line to a track and its parsed cues (cached per title + track).
   * @param {any} movieId @param {any[]} rows @param {string} lang @param {number} slot
   * @returns {Promise<Line | null>}
   */
  async function loadLine(movieId, rows, lang, slot) {
    const pick = N.pickTrack(rows, lang);
    if (!pick) {
      U.warn(`line ${slot} (${lang}): no text track with WebVTT for movieId=${movieId}; available: ${rows.filter((t) => t.url).map((t) => t.lang).join(', ') || 'none'}`);
      return null;
    }
    const key = `${movieId}|${pick.id}`;
    let cues = cueCache.get(key);
    if (!cues) {
      let text = '';
      try {
        const resp = await fetch(pick.url);
        if (!resp.ok) throw new Error('HTTP ' + resp.status);
        text = await resp.text();
      } catch (err) {
        U.warn(`slot ${slot}: subtitle fetch failed for ${pick.lang} (${String(err).slice(0, 120)})`);
        return null;
      }
      const parsed = MC_SUBS.parseWebVTT(text);
      for (const w of parsed.warnings) U.warn(`webvtt (${pick.lang}):`, w);
      if (!parsed.cues.length) return null;
      cues = parsed.cues;
      for (const cue of cues) cue.norm = MC_SUBS.normalizeForMatch(cue.text);
      cueCache.set(key, cues);
      if (cueCache.size > 12) cueCache.delete(cueCache.keys().next().value);
    }
    return { pick, cues, raw: cues, cursor: { i: 0 }, hans: /^zh(-hans)?$/i.test(String(pick.lang)) };
  }

  // ---- pinyin: load the dictionary when a Simplified line wants it -----------------------
  const PINYIN_URL = chrome.runtime.getURL('data/pinyin.json');
  let pinyinWarned = false;
  /** @param {Session} s */
  function ensurePinyin(s) {
    if (MC_SETTINGS.get().pinyin === 'none' || MC_PINYIN.isReady() || !s.lines.some((l) => l && l.hans)) return;
    MC_PINYIN.load(PINYIN_URL).then(() => {
      const sz = MC_PINYIN.size;
      mark('pinyin:ready', `dictionary loaded: ${sz ? `${sz.words} words, ${sz.chars} chars` : '?'}`);
      if (session) session.lastKey = '';
    }).catch((err) => {
      if (!pinyinWarned) { pinyinWarned = true; U.warn('pinyin dictionary failed to load (is data/pinyin.json web-accessible in manifest.json?):', err); }
    });
  }

  /** @param {string} why */
  function stopSession(why) {
    if (!session) return;
    session.stopped = true;
    cancelAnimationFrame(session.raf);
    mark('session:stop', `movieId=${session.movieId} (${why})`);
    session = null;
    assist.reset();
    overlay.detach();
    applyNativeVisibility();
  }

  function frame() {
    const s = session;
    if (!s || s.stopped) return;
    s.raf = requestAnimationFrame(frame);
    if (!video || !video.isConnected) return;
    if (!overlay.mounted) overlay.attach(video, SLOTS, overlayHost());
    const c = clock.now();
    const wrongMovie = c.movieId != null && String(c.movieId) !== String(s.movieId);
    const hidden = wrongMovie || c.inAd || !MC_SETTINGS.get().enabled;
    let texts = s.lines.map(() => '');
    let zhText = '';
    let zhEnd = -Infinity;
    if (!hidden) {
      let end = -Infinity;
      texts = s.lines.map((l) => {
        if (!l) return '';
        const active = MC_SUBS.activeCues(l.cues, c.t, l.cursor);
        for (const x of active) end = Math.max(end, x.end);
        const text = active.map((x) => x.text).join('\n');
        if (l.hans && text) { zhText = text; for (const x of active) zhEnd = Math.max(zhEnd, x.end); }
        return text;
      });
      if (texts.some(Boolean)) s.lastShown = { texts, end };
      else if (video.paused && s.lastShown && c.t >= s.lastShown.end - 0.5 && c.t - s.lastShown.end <= STICKY_S) texts = s.lastShown.texts; // reading time while paused
    }
    assist.update({ t: c.t, wall: performance.now(), paused: video.paused, inAd: c.inAd || hidden, zh: zhText, end: zhEnd });
    const pinyin = MC_SETTINGS.get().pinyin !== 'none' && MC_PINYIN.isReady();
    const key = JSON.stringify(texts) + (hidden ? '|hidden' : '') + (pinyin ? '|py' : '');
    if (key === s.lastKey) return;
    s.lastKey = key;
    s.cueChanges++;
    const annos = s.lines.map((l, i) => (pinyin && l && l.hans && texts[i] ? MC_PINYIN.annotate(texts[i]) : null));
    overlay.render(texts, !hidden, annos);
    if (texts.some(Boolean)) mark('cue', `content=${c.t.toFixed(3)} ${texts.map((t) => JSON.stringify(t.slice(0, 40))).join(' / ')}`, { quiet: true });
  }

  /** Where the overlay mounts: the player view (beside Netflix's pause card), if present. */
  function overlayHost() {
    return /** @type {HTMLElement | null} */ (document.querySelector(N.SEL.playerView));
  }

  /**
   * Netflix's own subtitle layer: invisible while we render (it keeps updating, which layer C
   * needs). A constructed stylesheet with !important survives Netflix rewriting the element's
   * style attribute (observed after an ad break); the inline opacity is a belt-and-braces
   * fallback re-applied on every tick.
   */
  /** @type {CSSStyleSheet | null} */
  let nativeSheet = null;
  function applyNativeVisibility() {
    const hide = !!session;
    try {
      if (!nativeSheet) {
        nativeSheet = new CSSStyleSheet();
        nativeSheet.replaceSync(`${N.SEL.timedtext} { opacity: 0 !important; }`);
        document.adoptedStyleSheets = [...document.adoptedStyleSheets, nativeSheet];
      }
      nativeSheet.disabled = !hide;
    } catch (err) {
      if (!nativeSheetWarned) { nativeSheetWarned = true; U.warn('constructed stylesheet unavailable; relying on inline opacity for the native layer:', err); }
    }
    if (ttEl instanceof HTMLElement && ttEl.style.opacity !== (hide ? '0' : '')) ttEl.style.opacity = hide ? '0' : '';
  }
  let nativeSheetWarned = false;

  /** Mount the picker inside the player view; mirror the control bar's visibility. */
  function pickerTick() {
    const onWatch = !!N.watchIdFromUrl(location.href);
    const view = onWatch ? /** @type {HTMLElement | null} */ (document.querySelector(N.SEL.playerView)) : null;
    if (view) picker.mount(view);
    else if (picker.mounted) picker.unmount();
    const cv = !!document.querySelector(N.SEL.controls) && !holdingUi;
    if (cv !== controlsVisible) {
      controlsVisible = cv;
      picker.setControlsVisible(cv);
      overlay.setRaised(cv);
    }
  }

  document.addEventListener('keydown', (e) => {
    if (!e.ctrlKey || !e.shiftKey || e.metaKey || e.altKey) return;
    if (e.code === 'KeyM') { picker.toggle(); e.preventDefault(); e.stopPropagation(); }
    else if (e.code === 'KeyH') { MC_SETTINGS.save({ enabled: !MC_SETTINGS.get().enabled }); e.preventDefault(); e.stopPropagation(); }
    else if (e.code === 'KeyP') { MC_SETTINGS.save({ assist: { pause: /** @type {any} */ (MC_SETTINGS.get().assist.pause === 'off' ? lastPauseMode : 'off') } }); e.preventDefault(); e.stopPropagation(); }
  }, true);

  function sessionSummary() {
    const st = MC_SETTINGS.get();
    if (!session) return { active: false, clockSource: clock.source, settings: st };
    const c = clock.now();
    return {
      active: true, movieId: session.movieId,
      lines: session.lines.map((l, i) => (l ? `${i}: ${l.pick.lang} "${l.pick.name}" (${l.pick.raw}) ${l.cues.length} cues` : `${i}: off`)),
      cueChanges: session.cueChanges, overlayMounted: overlay.mounted, pickerMounted: picker.mounted, settings: st,
      clock: { contentTime: +c.t.toFixed(3), inAd: c.inAd, source: c.source, mediaTime: video ? +video.currentTime.toFixed(3) : null },
      showing: session.lines.map((l) => (l ? MC_SUBS.activeCues(l.cues, c.t, { i: l.cursor.i }).map((x) => x.text).join('\n') : '')),
      pauseAdPresent, controlsVisible, clockStatus: clock.status(), assist: assist.status(),
      extended: session.lines.map((l) => (l ? l.cues.filter((c) => /** @type {any} */ (c).end0 != null).length : 0)),
    };
  }

  // ---- layer C matcher: native cue text → parsed cue start time ----------------------------
  // Cue text is normalized once at load (cue.norm). With an estimate, only cues within the
  // clock's window are considered and the nearest wins; without one, a unique text is required.
  clock.setMatcher((text, estimate) => {
    if (!session) return null;
    const want = MC_SUBS.normalizeForMatch(text);
    if (!want) return null;
    /** @type {number[]} */
    const hits = [];
    for (const line of session.lines) {
      if (!line) continue;
      for (const cue of line.cues) {
        if (estimate != null && Math.abs(cue.begin - estimate) > 60) continue;
        if (cue.norm === want) hits.push(cue.begin);
      }
    }
    if (!hits.length) return null;
    if (estimate == null) return { begin: hits[0], ambiguous: hits.length > 1 };
    hits.sort((a, b) => Math.abs(a - estimate) - Math.abs(b - estimate));
    return { begin: hits[0], ambiguous: hits.length > 1 && Math.abs(hits[1] - estimate) < 60 };
  });

  // ---- bridge wiring -----------------------------------------------------------------

  bridge.on('manifest', (m) => {
    mark('manifest', `movieId=${m.movieId} dur=${m.durationMs}ms tracks=${m.trackCount} adverts=${m.advertsSummary} aux=${m.auxCount}`);
    if (N.watchIdFromUrl(location.href)) startSession(m.movieId, 'new manifest');
    setTimeout(() => {
      const p = U.safe(() => bridge.call('probe'), null);
      if (!p) mark('probe', 'bridge call failed');
      else mark('probe', p.ok ? `ok session=${p.session} getters=${Object.keys(p.getters).length} clock=${U.summarize(p.clock)}` : `FAILED: ${p.error}`);
    }, 4000);
  });
  bridge.on('request', (r) => mark('request', `manifest request ${r.changes.length ? r.changes.join('; ') : 'seen, unchanged'} (params: ${r.paramKeys.join(', ')})`));
  bridge.handle('ping', () => 'pong');
  bridge.handle('report', () => ({
    startedAt,
    video: video ? videoDesc(video) : null,
    timeline: timeline.items(),
    uia: [...uiaStats].map(([v, s]) => ({ v, ...s })),
    nativeCueCount: ttCount,
    nativeCues: nativeCues.items().slice(-40),
    session: sessionSummary(),
  }));
  bridge.handle('session', sessionSummary);
  bridge.handle('overlay-set', (/** @type {{enabled?: boolean}} */ opts) => {
    if (opts && typeof opts.enabled === 'boolean') MC_SETTINGS.save({ enabled: opts.enabled });
    return { enabled: MC_SETTINGS.get().enabled };
  });
  bridge.handle('settings-get', () => MC_SETTINGS.get());
  bridge.handle('settings-set', (/** @type {any} */ patch) => {
    if (!patch || typeof patch !== 'object') return MC_SETTINGS.get();
    /** @type {{enabled?: boolean, pinyin?: any, style?: any, assist?: any}} */
    const clean = {};
    if (typeof patch.enabled === 'boolean') clean.enabled = patch.enabled;
    if (typeof patch.pinyin === 'string' || typeof patch.pinyin === 'boolean') clean.pinyin = patch.pinyin;
    if (patch.style && typeof patch.style === 'object') clean.style = patch.style;
    if (patch.assist && typeof patch.assist === 'object') clean.assist = patch.assist;
    MC_SETTINGS.save(clean);
    return MC_SETTINGS.get();
  });
  bridge.handle('sync', () => clock.status());
  bridge.handle('pinyin', (/** @type {string} */ text) => (MC_PINYIN.isReady() ? MC_PINYIN.describe(String(text)) : '(dictionary not loaded)'));
  bridge.handle('assist', () => assist.status());

  // ---- boot --------------------------------------------------------------------------

  // ---- manifest via the player graph + DOM ad flag (verified selectors) -----------

  let tickCount = 0;
  let domAd = false;

  function manifestTick() {
    const id = N.watchIdFromUrl(location.href);
    if (!id || tickCount % 4 !== 0) return;
    const ms = /** @type {any[]} */ (U.safe(() => bridge.call('manifests'), []) ?? []);
    if (ms.some((m) => String(m.movieId) === id)) return;
    const r = U.safe(() => bridge.call('manifest-check'), 'bridge unavailable');
    if (typeof r === 'string' && r.startsWith('captured')) mark('manifest:player', r);
  }

  function domAdTick() {
    const now = !!document.querySelector(N.SEL.adsInfo);
    if (now !== domAd) { domAd = now; mark('dom-ad', now ? `ON (${N.SEL.adsInfo} present)` : 'OFF'); }
    const pa = !!document.querySelector(N.SEL.pauseAd);
    if (pa !== pauseAdPresent) { pauseAdPresent = pa; mark('pause-ad', pa ? 'ON' : 'OFF', { quiet: true }); }
  }

  function tick() { tickCount++; videoTick(); timedTextTick(); urlTick(); manifestTick(); domAdTick(); pickerTick(); }

  function boot() {
    observer.observe(document.documentElement, { subtree: true, childList: true, characterData: true });
    setInterval(tick, 500);
    setInterval(clockTick, 10000);
    const pong = U.safe(() => bridge.call('ping'), null);
    if (pong !== 'pong') U.warn('page hook (MAIN world) not reachable — JSON hooks are NOT active. Check manifest.json content_scripts and that Chrome ≥ 111.');
    else U.log('phase-0 instrumentation active; page hook reachable. In the page console: __multicap.help()');
    tick();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
